INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('macro_01', 'macro', '碳水化合物', NULL, '大腦與紅血球最主要（幾乎唯一）的能量來源。分成好的（全穀、根莖、豆類）與精製的（白糖、白飯、含糖飲料）。', '{"name":"碳水化合物","emoji":"🍚","alias":"主要能量來源","role":"大腦與紅血球最主要（幾乎唯一）的能量來源。分成好的（全穀、根莖、豆類）與精製的（白糖、白飯、含糖飲料）。","dose":"占每日總熱量 50–60%；每日至少約 130g 維持大腦運作","foods":"全穀（糙米、燕麥）、地瓜、馬鈴薯、南瓜、豆類、水果","tip":"不是不能吃澱粉，是要選「原型、帶纖維」的——地瓜 > 白吐司，差別在血糖起伏。","warn":"精製糖與含糖飲料是最該減的碳水；完全不吃碳水易疲勞、掉髮、情緒差。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('macro_02', 'macro', '蛋白質', NULL, '構成肌肉、器官、酵素、荷爾蒙與免疫抗體。由 20 種胺基酸組成，其中 9 種必需胺基酸只能從食物取得。', '{"name":"蛋白質","emoji":"🍗","alias":"身體的建材","role":"構成肌肉、器官、酵素、荷爾蒙與免疫抗體。由 20 種胺基酸組成，其中 9 種必需胺基酸只能從食物取得。","dose":"一般成人每公斤體重 0.8–1.2g；規律運動／增肌者 1.2–2.0g","foods":"雞蛋、雞胸肉、魚、海鮮、黃豆製品、乳製品、瘦肉","tip":"每餐都要有一個手掌大的蛋白質，平均分配比一餐狂吃更好吸收。想知道 9 種必需胺基酸各自的作用，切到上方「胺基酸」分頁。","warn":"腎功能不佳者的蛋白質攝取量務必先諮詢醫師，不可自行高蛋白飲食。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('macro_03', 'macro', '脂質', NULL, '構成細胞膜、合成荷爾蒙、幫助脂溶性維生素（A、D、E、K）吸收。重點是「油的品質」而非完全不吃油。', '{"name":"脂質","emoji":"🥑","alias":"Omega-3/6/9","role":"構成細胞膜、合成荷爾蒙、幫助脂溶性維生素（A、D、E、K）吸收。重點是「油的品質」而非完全不吃油。","dose":"占每日總熱量 20–30%；Omega-3（EPA+DHA）約 250–500mg/日","foods":"好油：鮭魚、鯖魚、酪梨、橄欖油、堅果、亞麻仁\n少碰：油炸物、反式脂肪（酥油、乳瑪琳）","tip":"每週吃 2–3 次深海魚補 Omega-3；用橄欖油或苦茶油取代精製調和油。想細看飽和／單元／多元不飽和與反式脂肪的差別，切到上方「脂肪酸／油脂」分頁。","warn":"反式脂肪對心血管傷害最大，看到成分表有「氫化」就避開。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('macro_04', 'macro', '水', NULL, '占體重約 60%。運輸養分、排除廢物、調節體溫、潤滑關節。輕微脫水就會疲勞、頭痛、注意力下降。', '{"name":"水","emoji":"💧","alias":"最被忽略的營養素","role":"占體重約 60%。運輸養分、排除廢物、調節體溫、潤滑關節。輕微脫水就會疲勞、頭痛、注意力下降。","dose":"一般成人約 2000–3000ml/日（含食物水分）；約每公斤體重 30ml","foods":"白開水（最佳）、無糖茶、湯、蔬果（含水量高）","tip":"別等口渴才喝——尿液呈淡黃色代表水分剛好，深黃就是不夠了。","warn":"心臟、腎臟疾病患者的飲水量需依醫囑限制，不可一味多喝。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_01', 'amino', '白胺酸', NULL, '支鏈胺基酸之一，是啟動肌肉蛋白質合成（mTOR 路徑）最關鍵的開關，運動後補充特別重要。', '{"name":"白胺酸","emoji":"💪","alias":"必需胺基酸／支鏈BCAA","role":"支鏈胺基酸之一，是啟動肌肉蛋白質合成（mTOR 路徑）最關鍵的開關，運動後補充特別重要。","dose":"無單獨RDA；成人需求約每公斤體重 39mg/日","foods":"乳清蛋白、雞蛋、牛肉、雞肉、黃豆、鮪魚、乳製品","tip":"訓練後一份含足量白胺酸的蛋白質（約每餐2–3g白胺酸）最能刺激肌肉合成。","warn":"補充劑不能取代完整蛋白質；肝腎疾病者使用BCAA前請諮詢醫師。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_02', 'amino', '異白胺酸', NULL, '支鏈胺基酸之一，參與肌肉修復、運動時的能量供應與血糖調節。', '{"name":"異白胺酸","emoji":"🏋️","alias":"必需胺基酸／支鏈BCAA","role":"支鏈胺基酸之一，參與肌肉修復、運動時的能量供應與血糖調節。","dose":"約每公斤體重 20mg/日","foods":"蛋、瘦肉、魚、黃豆、起司、堅果、扁豆","tip":"BCAA（白／異白／纈胺酸）在完整蛋白質裡就有，均衡吃肉蛋豆魚就足夠。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_03', 'amino', '纈胺酸', NULL, '支鏈胺基酸之一，維持肌肉代謝、組織修復與神經系統正常運作。', '{"name":"纈胺酸","emoji":"🦵","alias":"必需胺基酸／支鏈BCAA","role":"支鏈胺基酸之一，維持肌肉代謝、組織修復與神經系統正常運作。","dose":"約每公斤體重 26mg/日","foods":"乳製品、肉類、菇類、黃豆、花生、全穀","tip":"三種BCAA協同作用，補充時比例均衡比單吃一種更有意義。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_04', 'amino', '離胺酸', NULL, '合成膠原蛋白、幫助鈣質吸收、製造肉鹼（把脂肪轉為能量）、支持免疫。', '{"name":"離胺酸","emoji":"🧱","alias":"必需胺基酸","role":"合成膠原蛋白、幫助鈣質吸收、製造肉鹼（把脂肪轉為能量）、支持免疫。","dose":"約每公斤體重 30mg/日","foods":"肉、魚、蛋、乳製品、黃豆、豆類（穀類含量偏低）","tip":"穀類離胺酸少、豆類豐富——「米飯配豆類」正好互補，這是素食蛋白質搭配的關鍵。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_05', 'amino', '甲硫胺酸', NULL, '含硫胺基酸，參與甲基化反應、肝臟解毒、合成肉鹼，也是蛋白質合成的起始胺基酸。', '{"name":"甲硫胺酸","emoji":"🧪","alias":"必需胺基酸／含硫","role":"含硫胺基酸，參與甲基化反應、肝臟解毒、合成肉鹼，也是蛋白質合成的起始胺基酸。","dose":"與半胱胺酸合計約每公斤 15mg/日","foods":"蛋、魚、肉、巴西堅果、芝麻、全穀","warn":"長期極高攝取與同半胱胺酸上升有關，需搭配足夠B6、B12、葉酸幫助代謝。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_06', 'amino', '苯丙胺酸', NULL, '是酪胺酸的前驅物，進而合成多巴胺、正腎上腺素等神經傳導物質，影響情緒與警覺。', '{"name":"苯丙胺酸","emoji":"🧠","alias":"必需胺基酸","role":"是酪胺酸的前驅物，進而合成多巴胺、正腎上腺素等神經傳導物質，影響情緒與警覺。","dose":"與酪胺酸合計約每公斤 25mg/日","foods":"肉、魚、蛋、乳製品、黃豆、南瓜籽","warn":"苯酮尿症（PKU）患者無法代謝苯丙胺酸，必須嚴格限制，含阿斯巴甜的代糖也要避開。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_07', 'amino', '蘇胺酸', NULL, '構成膠原蛋白與彈力蛋白、維持腸道黏膜屏障、支持抗體與免疫功能。', '{"name":"蘇胺酸","emoji":"🛡️","alias":"必需胺基酸","role":"構成膠原蛋白與彈力蛋白、維持腸道黏膜屏障、支持抗體與免疫功能。","dose":"約每公斤體重 15mg/日","foods":"蛋、瘦肉、魚、扁豆、堅果、芝麻","tip":"腸道黏膜更新快、需求高——腸胃道健康和足夠蛋白質息息相關。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_08', 'amino', '色胺酸', NULL, '是血清素（穩定情緒）與褪黑激素（幫助入睡）的前驅物，也參與菸鹼酸（B3）合成。', '{"name":"色胺酸","emoji":"😴","alias":"必需胺基酸／助眠","role":"是血清素（穩定情緒）與褪黑激素（幫助入睡）的前驅物，也參與菸鹼酸（B3）合成。","dose":"約每公斤體重 4mg/日","foods":"牛奶、香蕉、燕麥、火雞肉、黃豆、堅果、南瓜籽","tip":"睡前一杯溫牛奶的「助眠」說法有部分根據——色胺酸配一點碳水更容易進入大腦。","warn":"正在服用抗憂鬱藥（尤其SSRI）者，額外補充色胺酸／5-HTP前務必諮詢醫師，以免血清素過量。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_09', 'amino', '組胺酸', NULL, '合成組織胺（免疫與發炎反應）、維持血紅素與神經髓鞘，對嬰幼兒成長尤其重要。', '{"name":"組胺酸","emoji":"🩸","alias":"必需胺基酸","role":"合成組織胺（免疫與發炎反應）、維持血紅素與神經髓鞘，對嬰幼兒成長尤其重要。","dose":"約每公斤體重 10mg/日","foods":"肉、魚、蛋、全穀、黃豆、乳製品","tip":"成人可少量自製，但仍歸類為必需——嬰幼兒與生長期需求較高。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_10', 'amino', '麩醯胺酸', NULL, '血液中含量最高的胺基酸，是腸道細胞與免疫細胞的主要燃料；重病、手術、劇烈運動等壓力下需求會超過自製能力。', '{"name":"麩醯胺酸","emoji":"🦠","alias":"條件性必需（壓力下）","role":"血液中含量最高的胺基酸，是腸道細胞與免疫細胞的主要燃料；重病、手術、劇烈運動等壓力下需求會超過自製能力。","dose":"無RDA；一般飲食即足夠","foods":"肉、蛋、乳製品、黃豆、甘藍、菠菜","warn":"健康者通常不需額外補充；肝腎疾病者補充前請諮詢醫師。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_11', 'amino', '精胺酸', NULL, '是一氧化氮（NO）的原料，能放鬆血管、促進血液循環，也參與傷口癒合與免疫。成長期、受傷或重病時需求增加。', '{"name":"精胺酸","emoji":"🫀","alias":"條件性必需","role":"是一氧化氮（NO）的原料，能放鬆血管、促進血液循環，也參與傷口癒合與免疫。成長期、受傷或重病時需求增加。","dose":"無RDA","foods":"堅果、南瓜籽、黃豆、肉、海鮮、全穀","warn":"心血管疾病、低血壓或正服用相關藥物者，高劑量補充前請諮詢醫師。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_12', 'amino', '甘胺酸', NULL, '結構最小的胺基酸，是膠原蛋白的主要成分（約占三分之一）、合成抗氧化物穀胱甘肽與膽汁，也與睡眠品質有關。', '{"name":"甘胺酸","emoji":"🧵","alias":"條件性必需（最小胺基酸）","role":"結構最小的胺基酸，是膠原蛋白的主要成分（約占三分之一）、合成抗氧化物穀胱甘肽與膽汁，也與睡眠品質有關。","dose":"無RDA","foods":"骨頭湯、豬皮、雞皮、明膠、豆類、魚","tip":"膠原蛋白富含甘胺酸——但只要蛋白質吃夠，身體會自行合成需要的膠原，不一定要買補充品。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_13', 'amino', '酪胺酸', NULL, '由苯丙胺酸轉化而來，是多巴胺、正腎上腺素、腎上腺素與甲狀腺素的共同前驅物，影響專注、動力與代謝。', '{"name":"酪胺酸","emoji":"⚡","alias":"條件性必需","role":"由苯丙胺酸轉化而來，是多巴胺、正腎上腺素、腎上腺素與甲狀腺素的共同前驅物，影響專注、動力與代謝。","dose":"無RDA","foods":"起司、黃豆、雞肉、魚、蛋、酪梨、南瓜籽","tip":"苯酮尿症患者無法把苯丙胺酸轉成酪胺酸，酪胺酸對他們反而變成必需。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('amino_14', 'amino', '半胱胺酸', NULL, '含硫胺基酸，是抗氧化主力「穀胱甘肽」的關鍵原料，也構成頭髮與指甲的角蛋白。', '{"name":"半胱胺酸","emoji":"💇","alias":"條件性必需／含硫","role":"含硫胺基酸，是抗氧化主力「穀胱甘肽」的關鍵原料，也構成頭髮與指甲的角蛋白。","dose":"與甲硫胺酸合計計算","foods":"蛋、肉、大蒜、洋蔥、青花菜、燕麥","tip":"身體可由甲硫胺酸轉換半胱胺酸，含硫蔬菜（蒜、洋蔥、十字花科）也有幫助。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('fat_01', 'fat', '飽和脂肪酸', NULL, '碳鏈上沒有雙鍵、結構穩定、室溫多為固態。是能量與細胞膜的原料，但過量會升高LDL（壞膽固醇）。', '{"name":"飽和脂肪酸","emoji":"🧈","alias":"Saturated fat","role":"碳鏈上沒有雙鍵、結構穩定、室溫多為固態。是能量與細胞膜的原料，但過量會升高LDL（壞膽固醇）。","dose":"建議低於每日總熱量10%（心血管高風險者更低）","foods":"肥肉、奶油、豬油、椰子油、棕櫚油、全脂乳製品","tip":"不必完全禁絕，但別當主要油脂——把一部分換成橄欖油、堅果等不飽和油更護心。","warn":"心血管疾病或高膽固醇者尤其要控制飽和脂肪比例。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('fat_02', 'fat', '單元不飽和脂肪酸', NULL, '碳鏈上有一個雙鍵。能幫助降低LDL、維持HDL（好膽固醇），是地中海飲食護心的核心油脂。', '{"name":"單元不飽和脂肪酸","emoji":"🫒","alias":"MUFA／Omega-9・油酸","role":"碳鏈上有一個雙鍵。能幫助降低LDL、維持HDL（好膽固醇），是地中海飲食護心的核心油脂。","dose":"可作為主要油脂來源，取代部分飽和脂肪","foods":"橄欖油、苦茶油、酪梨、酪梨油、腰果、杏仁、花生","tip":"日常炒菜用橄欖油或苦茶油取代精製調和油，是最容易做到的護心習慣。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('fat_03', 'fat', '多元不飽和脂肪酸', NULL, '碳鏈上有兩個以上雙鍵，包含人體無法自行合成、必須從食物取得的「必需脂肪酸」——Omega-3 與 Omega-6。', '{"name":"多元不飽和脂肪酸","emoji":"🐟","alias":"PUFA／必需脂肪酸","role":"碳鏈上有兩個以上雙鍵，包含人體無法自行合成、必須從食物取得的「必需脂肪酸」——Omega-3 與 Omega-6。","dose":"Omega-3與Omega-6都需要，重點是兩者比例平衡","foods":"深海魚、亞麻仁、核桃、葵花油、大豆油、堅果","tip":"多元不飽和油不耐高溫，適合涼拌或低溫烹調，高溫油炸容易氧化變質。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('fat_04', 'fat', 'Omega-3', NULL, '抗發炎、保護心血管、支持大腦與視網膜（DHA）。現代飲食普遍攝取不足。', '{"name":"Omega-3","emoji":"🐠","alias":"必需脂肪酸（EPA／DHA／ALA）","role":"抗發炎、保護心血管、支持大腦與視網膜（DHA）。現代飲食普遍攝取不足。","dose":"EPA+DHA約250–500mg/日；每週2–3次深海魚","foods":"鮭魚、鯖魚、秋刀魚、沙丁魚、亞麻仁、奇亞籽、核桃","tip":"植物來源（亞麻仁的ALA）轉換成EPA／DHA效率低，吃魚或藻油較直接；素食者可選藻油。","warn":"服用抗凝血藥物者高劑量魚油補充前請諮詢醫師。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('fat_05', 'fat', 'Omega-6', NULL, '人體必需，參與細胞膜構成與發炎調節。本身不是壞油，但現代飲食（大量植物油、加工食品）常攝取過多，與Omega-3失衡。', '{"name":"Omega-6","emoji":"🌻","alias":"必需脂肪酸（亞油酸）","role":"人體必需，參與細胞膜構成與發炎調節。本身不是壞油，但現代飲食（大量植物油、加工食品）常攝取過多，與Omega-3失衡。","dose":"需要但少缺；重點是提高Omega-3、別再過量Omega-6","foods":"大豆油、葵花油、玉米油、堅果、種子","tip":"少吃油炸與加工食品、多吃魚，就能自然改善Omega-6／Omega-3的比例。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('fat_06', 'fat', '反式脂肪', NULL, '少量天然存在於反芻動物，但危害主要來自「部分氫化植物油」的人工反式脂肪。它同時升高LDL、降低HDL，是最傷心血管的脂肪。', '{"name":"反式脂肪","emoji":"🚫","alias":"對心血管最有害的脂肪","role":"少量天然存在於反芻動物，但危害主要來自「部分氫化植物油」的人工反式脂肪。它同時升高LDL、降低HDL，是最傷心血管的脂肪。","dose":"越少越好、理想為零；WHO呼籲全球全面淘汰人工反式脂肪","foods":"（應避免）酥油、乳瑪琳、奶精、部分烘焙品、油炸物、酥皮、部分餅乾","tip":"看成分表：出現「氫化」「部分氫化」「植物性乳化油」「人造奶油」就放回架上。","warn":"台灣自2018年起禁止食品使用不完全氫化油（人工反式脂肪），但仍需留意標示與含量。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('fat_07', 'fat', '膽固醇', NULL, '構成細胞膜、合成性荷爾蒙、維生素D與膽汁。約七至八成由肝臟自行製造，飲食只占少部分。', '{"name":"膽固醇","emoji":"🥚","alias":"類脂質","role":"構成細胞膜、合成性荷爾蒙、維生素D與膽汁。約七至八成由肝臟自行製造，飲食只占少部分。","dose":"新版指引不再訂單一上限；重點是控制飽和與反式脂肪","foods":"蛋黃、內臟、海鮮、動物性食品","tip":"對多數人而言，吃進的膽固醇對血膽固醇影響有限——控制飽和／反式脂肪、多運動更關鍵。健康者一天一顆蛋沒問題。","warn":"已有高膽固醇、心血管疾病或家族性高膽固醇血症者，飲食仍需依醫囑個別化調整。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_01', 'vitamin', '維生素A', NULL, '維持視力、皮膚屏障、免疫功能。缺乏時夜間視力變差、皮膚乾燥。', '{"name":"維生素A","emoji":"🥕","alias":"視黃醇（脂溶性）","role":"維持視力、皮膚屏障、免疫功能。缺乏時夜間視力變差、皮膚乾燥。","dose":"男 600 / 女 500 μg RAE；上限 UL 3000μg","foods":"動物性：肝臟、蛋黃、奶油\n植物性（β-胡蘿蔔素轉化）：胡蘿蔔、地瓜、南瓜、菠菜、芒果","tip":"β-胡蘿蔔素配油脂吸收更好——炒紅蘿蔔比生吃有效。","warn":"動物性來源（尤其補充劑）過量有肝毒性與致畸性，孕婦不可補高劑量A。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_02', 'vitamin', '維生素B1', NULL, '把碳水化合物轉化為能量、維持神經功能。缺乏時容易疲勞、食慾不振、腳麻。', '{"name":"維生素B1","emoji":"🌾","alias":"硫胺素（水溶性）","role":"把碳水化合物轉化為能量、維持神經功能。缺乏時容易疲勞、食慾不振、腳麻。","dose":"男 1.2 / 女 0.9 mg；水溶性無明確上限","foods":"糙米、燕麥、全穀、豬肉、豆類、葵花籽","tip":"白米幾乎不含B1——如果主食是白飯，搭配豬肉或豆類補回來。","warn":"精製加工會大量流失，長期大量飲酒會嚴重消耗B1。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_03', 'vitamin', '維生素B2', NULL, '參與能量代謝、維持皮膚黏膜。缺乏時嘴破、嘴角炎、眼睛怕光。', '{"name":"維生素B2","emoji":"🥛","alias":"核黃素（水溶性）","role":"參與能量代謝、維持皮膚黏膜。缺乏時嘴破、嘴角炎、眼睛怕光。","dose":"男 1.3 / 女 1.0 mg；水溶性無明確上限","foods":"牛奶、優格、蛋、香菇、內臟、杏仁","tip":"容易嘴破的人，先檢查B2夠不夠——一杯牛奶+一顆蛋就接近每日需求。","warn":"光照會破壞B2，牛奶不要放在透明容器曬太陽。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_04', 'vitamin', '維生素B3', NULL, '能量代謝、維持皮膚和神經系統、調節血脂。', '{"name":"維生素B3","emoji":"🍗","alias":"菸鹼酸（水溶性）","role":"能量代謝、維持皮膚和神經系統、調節血脂。","dose":"男 16 / 女 14 mg NE；補充劑上限 UL 35mg","foods":"雞胸肉、鮪魚、花生、蘑菇、全穀、肝臟","tip":"色胺酸可以在體內轉化為菸鹼酸——所以喝牛奶也算間接補充。","warn":"高劑量補充可能引起臉紅、皮膚發燙（菸鹼酸潮紅），有肝毒性風險。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_05', 'vitamin', '維生素B5', NULL, '合成輔酶A、參與能量與脂肪代謝、製造荷爾蒙。名字源於「無所不在」，缺乏罕見。', '{"name":"維生素B5","emoji":"🥚","alias":"泛酸（水溶性）","role":"合成輔酶A、參與能量與脂肪代謝、製造荷爾蒙。名字源於「無所不在」，缺乏罕見。","dose":"適當攝取量 AI 5mg；水溶性無明確上限","foods":"蛋黃、內臟、酪梨、香菇、全穀、雞肉、優格","tip":"分布極廣，正常飲食幾乎不會缺——不需特別補充。","warn":"極高劑量補充可能引起腹瀉。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_06', 'vitamin', '維生素B6', NULL, '蛋白質代謝、神經傳導物質（血清素）合成、紅血球生成。', '{"name":"維生素B6","emoji":"🍌","alias":"吡哆醇（水溶性）","role":"蛋白質代謝、神經傳導物質（血清素）合成、紅血球生成。","dose":"1.5 mg；補充劑上限 UL 80mg","foods":"香蕉、雞胸肉、鮭魚、馬鈴薯、鷹嘴豆、葵花籽","tip":"高蛋白飲食的人需要更多B6來代謝蛋白質。","warn":"長期高劑量補充（>100mg/天）可能導致神經損傷、手腳麻木。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_07', 'vitamin', '維生素B7', NULL, '參與醣類、脂肪、蛋白質代謝，維持頭髮、皮膚、指甲健康。', '{"name":"維生素B7","emoji":"🥜","alias":"生物素（水溶性）","role":"參與醣類、脂肪、蛋白質代謝，維持頭髮、皮膚、指甲健康。","dose":"適當攝取量 AI 30μg；無明確上限","foods":"蛋黃（煮熟）、堅果、全穀、鮭魚、豬肉、地瓜","tip":"生蛋白會抓住生物素影響吸收，蛋要煮熟吃。","warn":"高劑量生物素補充會干擾甲狀腺與心肌等抽血檢驗數值，抽血前請告知醫師。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_08', 'vitamin', '葉酸', NULL, 'DNA合成、細胞分裂、紅血球生成。孕期不足會增加胎兒神經管缺陷風險。', '{"name":"葉酸","emoji":"🥦","alias":"維生素B9（水溶性）","role":"DNA合成、細胞分裂、紅血球生成。孕期不足會增加胎兒神經管缺陷風險。","dose":"400 μg DFE；孕婦 600μg；補充劑上限 UL 1000μg","foods":"菠菜、蘆筍、豆類、肝臟、柑橘、酪梨","tip":"備孕女性應在懷孕前 3 個月就開始補充葉酸（400μg/天）。","warn":"葉酸怕熱怕水——蔬菜別煮太久；高劑量會掩蓋B12缺乏，補充前宜諮詢。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_09', 'vitamin', '維生素B12', NULL, '造血、維持神經髓鞘、DNA合成。缺乏導致惡性貧血、手腳麻木、認知退化。', '{"name":"維生素B12","emoji":"🥩","alias":"鈷胺素（水溶性）","role":"造血、維持神經髓鞘、DNA合成。缺乏導致惡性貧血、手腳麻木、認知退化。","dose":"2.4 μg；無明確上限","foods":"肉類、海鮮、蛋、乳製品（植物幾乎不含）","tip":"純素食者一定要額外補充B12，靠海苔或味噌是不夠的。","warn":"B12缺乏症狀可能數年後才出現，素食者與長者應定期抽血檢查。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_10', 'vitamin', '維生素C', NULL, '膠原蛋白合成、免疫增強、促進鐵吸收、抗氧化。', '{"name":"維生素C","emoji":"🍊","alias":"抗壞血酸（水溶性）","role":"膠原蛋白合成、免疫增強、促進鐵吸收、抗氧化。","dose":"100 mg；補充劑上限 UL 2000mg","foods":"芭樂（維C之王）、奇異果、甜椒、柑橘、草莓、花椰菜","tip":"吃素鐵不足時，飯後吃一顆芭樂幫助植物性鐵吸收，效果驚人。","warn":"加熱會大量破壞——水果生吃、蔬菜快炒；一次超過2000mg可能腹瀉、結石。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_11', 'vitamin', '維生素D', NULL, '促進鈣吸收、骨骼健康、免疫調節、情緒穩定。', '{"name":"維生素D","emoji":"☀️","alias":"陽光維生素（脂溶性）","role":"促進鈣吸收、骨骼健康、免疫調節、情緒穩定。","dose":"成人 10μg(400IU)；50歲以上 15μg(600IU)；上限 UL 50μg(2000IU)","foods":"日曬15-20分鐘（最佳來源）、鮭魚、鯖魚、蛋黃、曬過的香菇","tip":"台灣人超過六成維D不足——不是飲食問題，是不曬太陽。每天露手臂曬15分鐘。","warn":"脂溶性會累積，長期過量補充會導致高血鈣；補充前建議先驗血。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_12', 'vitamin', '維生素E', NULL, '抗氧化、保護細胞膜、皮膚修復。', '{"name":"維生素E","emoji":"🫒","alias":"生育醇（脂溶性）","role":"抗氧化、保護細胞膜、皮膚修復。","dose":"12 mg α-TE；補充劑上限 UL 1000mg","foods":"堅果（杏仁最多）、葵花籽、植物油、酪梨、菠菜","tip":"每天一小把堅果（約10顆杏仁）就能滿足大部分需求。","warn":"天然維E比合成的吸收率高；高劑量補充可能增加出血風險。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('vitamin_13', 'vitamin', '維生素K', NULL, '血液凝固、骨骼鈣化。K1來自植物，K2來自發酵食物。', '{"name":"維生素K","emoji":"🥬","alias":"凝血維生素（脂溶性）","role":"血液凝固、骨骼鈣化。K1來自植物，K2來自發酵食物。","dose":"適當攝取量 AI 男 120 / 女 90 μg","foods":"K1：深綠色蔬菜（羽衣甘藍、菠菜、花椰菜）\nK2：納豆（最佳來源）、起司、蛋黃","tip":"吃深綠色蔬菜配油脂——清燙菠菜不如炒菠菜吸收好。","warn":"服用抗凝血藥物（如華法林 Warfarin）者需維持維K攝取穩定，務必諮詢醫師。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_01', 'mineral', '鈣', NULL, '骨骼和牙齒的主要成分、肌肉收縮、神經傳導、血液凝固。', '{"name":"鈣","emoji":"🦴","alias":"骨骼之王","role":"骨骼和牙齒的主要成分、肌肉收縮、神經傳導、血液凝固。","dose":"1000 mg；補充劑上限 UL 2500mg","foods":"牛奶、優格、起司、小魚乾、板豆腐、黑芝麻、深綠色蔬菜","tip":"鈣+維生素D是黃金組合——單吃鈣片不曬太陽等於白吃。","warn":"茶、咖啡、菠菜中的草酸會抑制鈣吸收，不要同時大量攝取。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_02', 'mineral', '鐵', NULL, '血紅素核心成分，運送氧氣到全身。缺乏導致貧血、疲勞、臉色蒼白。', '{"name":"鐵","emoji":"🩸","alias":"造血元素","role":"血紅素核心成分，運送氧氣到全身。缺乏導致貧血、疲勞、臉色蒼白。","dose":"男 10 / 女 15 mg（停經後 10）；補充劑上限 UL 40mg","foods":"血鐵質（吸收率高）：紅肉、肝臟、鴨血\n非血鐵質：菠菜、紅豆、黑芝麻、葡萄乾","tip":"植物性鐵吸收率只有動物性的1/5——搭配維生素C可以提升3-6倍。","warn":"茶和咖啡的單寧酸會抑制鐵吸收；補鐵過量會傷肝，勿自行長期高劑量補。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_03', 'mineral', '鋅', NULL, '免疫功能、傷口癒合、味覺嗅覺、蛋白質合成、生殖健康。', '{"name":"鋅","emoji":"🛡️","alias":"免疫守門員","role":"免疫功能、傷口癒合、味覺嗅覺、蛋白質合成、生殖健康。","dose":"男 15 / 女 12 mg；補充劑上限 UL 35mg","foods":"牡蠣（含鋅之王）、牛肉、南瓜籽、腰果、蟹、全穀","tip":"感冒初期補充鋅含片可能縮短病程——但要在24小時內開始。","warn":"鋅和鐵、銅會互相競爭吸收，高劑量鋅補充品不要和鐵一起吃。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_04', 'mineral', '鎂', NULL, '肌肉放鬆、神經穩定、睡眠品質、能量產生、血糖調節。缺乏時容易抽筋。', '{"name":"鎂","emoji":"💤","alias":"放鬆礦物質","role":"肌肉放鬆、神經穩定、睡眠品質、能量產生、血糖調節。缺乏時容易抽筋。","dose":"男 380 / 女 320 mg；補充劑上限 UL 350mg（不含食物）","foods":"堅果（腰果、杏仁）、深綠色蔬菜、香蕉、黑巧克力、全穀、酪梨","tip":"睡前腳抽筋？肌肉緊繃？壓力大？先想想鎂夠不夠。","warn":"台灣人普遍缺鎂；補充劑過量會腹瀉，腎功能不佳者需諮詢醫師。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_05', 'mineral', '鉀', NULL, '維持正常血壓、心臟節律、肌肉功能、體液平衡。是得舒（DASH）飲食核心。', '{"name":"鉀","emoji":"💓","alias":"血壓調節者","role":"維持正常血壓、心臟節律、肌肉功能、體液平衡。是得舒（DASH）飲食核心。","dose":"適當攝取量 AI 約 3500mg（WHO 建議 ≥3510mg）","foods":"香蕉、馬鈴薯（帶皮）、地瓜、酪梨、菠菜、柳橙、番茄","tip":"鉀和鈉要平衡——吃太鹹就要多吃蔬果來補鉀，不是光喝水。","warn":"腎功能不好的人排鉀能力差，高血鉀有心律不整風險，攝取量務必遵醫囑。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_06', 'mineral', '鈉', NULL, '維持體液平衡、神經傳導、肌肉收縮。身體需要，但現代人幾乎都攝取過量。', '{"name":"鈉","emoji":"🧂","alias":"雙面刃電解質","role":"維持體液平衡、神經傳導、肌肉收縮。身體需要，但現代人幾乎都攝取過量。","dose":"建議 <2400mg（食鹽 <6g）；WHO 建議鈉 <2000mg","foods":"食鹽、醬油、加工食品、醃漬物、湯麵湯底、零食","tip":"減鈉不是吃無味——用蔥薑蒜、檸檬、香料提味，慢慢降低對鹹的依賴。","warn":"高鈉與高血壓、心血管疾病、腎臟負擔直接相關；外食族最該注意的就是鈉。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_07', 'mineral', '碘', NULL, '甲狀腺荷爾蒙的原料，調節新陳代謝與生長發育。缺乏導致甲狀腺腫大。', '{"name":"碘","emoji":"🦋","alias":"甲狀腺燃料","role":"甲狀腺荷爾蒙的原料，調節新陳代謝與生長發育。缺乏導致甲狀腺腫大。","dose":"140 μg；補充劑上限 UL 1000μg","foods":"海帶、紫菜、碘鹽、海魚、蝦、蛤蜊","tip":"如果你用的是玫瑰鹽或進口岩鹽，可能沒加碘——偶爾吃點海帶味噌湯。","warn":"碘過量也會影響甲狀腺——不需要天天大量吃海帶；甲狀腺疾病者請諮詢醫師。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_08', 'mineral', '硒', NULL, '強效抗氧化、甲狀腺功能、免疫力、精子健康。', '{"name":"硒","emoji":"🌰","alias":"抗氧化將軍","role":"強效抗氧化、甲狀腺功能、免疫力、精子健康。","dose":"55 μg；補充劑上限 UL 400μg","foods":"巴西堅果（1-2顆就夠）、海鮮、蛋、蒜、全穀","tip":"巴西堅果是硒含量最高的食物——每天1-2顆，不要多吃。","warn":"硒的安全範圍很窄，過量會中毒（掉髮、指甲脆裂、蒜味口氣）。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_09', 'mineral', '磷', NULL, '骨骼和牙齒結構、能量代謝（ATP）、細胞膜成分。', '{"name":"磷","emoji":"🧬","alias":"能量搬運工","role":"骨骼和牙齒結構、能量代謝（ATP）、細胞膜成分。","dose":"800 mg；補充劑上限 UL 4000mg","foods":"肉類、乳製品、堅果、全穀、豆類、蛋","tip":"磷通常不會缺——現代飲食反而容易攝取過量（加工食品含磷添加物）。","warn":"磷太多會影響鈣吸收；腎臟病患者需嚴格限磷，少喝含磷酸的可樂汽水。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_10', 'mineral', '鉻', NULL, '增強胰島素敏感度，幫助血糖調節。', '{"name":"鉻","emoji":"📊","alias":"血糖穩定器","role":"增強胰島素敏感度，幫助血糖調節。","dose":"適當攝取量 AI 男 35 / 女 25 μg","foods":"全穀、花椰菜、雞肉、馬鈴薯、蛋黃、堅果","tip":"精製糖會加速鉻的流失——吃越多甜食，身體需要的鉻就越多。","warn":"正常飲食通常足夠；糖尿病患者勿自行以鉻補充劑取代藥物。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_11', 'mineral', '銅', NULL, '協助鐵的運送與利用、形成紅血球、維持結締組織與神經、是抗氧化酵素的成分。', '{"name":"銅","emoji":"🟤","alias":"造血好夥伴","role":"協助鐵的運送與利用、形成紅血球、維持結締組織與神經、是抗氧化酵素的成分。","dose":"適當攝取量 AI 約 0.9mg；補充劑上限 UL 10mg","foods":"內臟（肝）、牡蠣、堅果、種子、全穀、黑巧克力、香菇","tip":"補鐵無效的貧血，有時是缺銅——銅幫助鐵被身體利用。","warn":"長期大量補鋅會抑制銅吸收，可能導致銅缺乏。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('mineral_12', 'mineral', '錳', NULL, '參與骨骼形成、抗氧化酵素（SOD）運作、醣類與脂肪代謝。', '{"name":"錳","emoji":"⚙️","alias":"骨骼與抗氧化酵素","role":"參與骨骼形成、抗氧化酵素（SOD）運作、醣類與脂肪代謝。","dose":"適當攝取量 AI 男 4.0 / 女 3.0 mg；補充劑上限 UL 11mg","foods":"全穀、糙米、堅果、豆類、鳳梨、菠菜、茶","tip":"全穀與堅果吃得夠，錳幾乎不會缺。","warn":"過量多來自污染或補充劑，可能影響神經系統；正常飲食安全。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('fiber_01', 'fiber', '水溶性膳食纖維', NULL, '溶於水形成膠狀，延緩糖分吸收、穩定血糖、抓住膽固醇排出、增加飽足感。', '{"name":"水溶性膳食纖維","emoji":"🥣","alias":"果膠、葡甘聚糖、β-葡聚醣","role":"溶於水形成膠狀，延緩糖分吸收、穩定血糖、抓住膽固醇排出、增加飽足感。","dose":"總膳食纖維每日 25–35g（水溶+非水溶）","foods":"燕麥、蘋果、柑橘、豆類、木耳、秋葵、蒟蒻","tip":"想穩血糖、降膽固醇——早餐一碗燕麥粥是最簡單的起點。","warn":"突然大量增加纖維會脹氣，要循序漸進並搭配足夠喝水。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('fiber_02', 'fiber', '非水溶性膳食纖維', NULL, '不溶於水，像掃把一樣增加糞便體積、促進腸道蠕動、預防便祕與大腸憩室。', '{"name":"非水溶性膳食纖維","emoji":"🥬","alias":"纖維素、木質素","role":"不溶於水，像掃把一樣增加糞便體積、促進腸道蠕動、預防便祕與大腸憩室。","dose":"總膳食纖維每日 25–35g（水溶+非水溶）","foods":"全穀、糙米、蔬菜梗、芹菜、地瓜、堅果、菇類","tip":"便祕時「纖維+水+運動」三者缺一不可，光吃纖維不喝水反而更硬。","warn":"腸道狹窄、術後或急性腸炎患者需限制纖維，請依醫囑調整。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('fiber_03', 'fiber', '益生元／寡糖', NULL, '人體不消化，但能餵養腸道益生菌，維護腸道微生態、增強免疫、幫助礦物質吸收。', '{"name":"益生元／寡糖","emoji":"🧅","alias":"Prebiotics（腸道好菌的食物）","role":"人體不消化，但能餵養腸道益生菌，維護腸道微生態、增強免疫、幫助礦物質吸收。","dose":"無明確建議量；由多元蔬果全穀自然攝取","foods":"洋蔥、大蒜、蘆筍、香蕉（微生）、菊苣、全穀、豆類","tip":"益生元是益生菌的「飼料」——補了益生菌也要餵它，兩者一起效果更好。","warn":"腸躁症（IBS）患者對某些寡糖（FODMAP）敏感，可能脹氣，需個別調整。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_01', 'phyto', 'β-胡蘿蔔素', NULL, '抗氧化，並可在體內依需求轉化為維生素A，保護視力與皮膚黏膜。', '{"name":"β-胡蘿蔔素","emoji":"🥕","alias":"類胡蘿蔔素／維生素A前驅物","role":"抗氧化，並可在體內依需求轉化為維生素A，保護視力與皮膚黏膜。","dose":"無明確RDA；由深黃橙紅蔬果攝取","foods":"胡蘿蔔、地瓜、南瓜、木瓜、芒果、深綠色蔬菜","tip":"配油脂吸收更好，且由食物攝取的β-胡蘿蔔素不會造成維生素A中毒。","warn":"吸菸者長期高劑量β-胡蘿蔔素「補充劑」可能增加肺癌風險，從食物攝取則安全。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_02', 'phyto', '茄紅素', NULL, '強效抗氧化、保護心血管、與降低前列腺癌風險有關。', '{"name":"茄紅素","emoji":"🍅","alias":"類胡蘿蔔素","role":"強效抗氧化、保護心血管、與降低前列腺癌風險有關。","dose":"無明確RDA","foods":"番茄（煮熟+油脂吸收提升5倍）、西瓜、紅葡萄柚、紅甜椒、木瓜","tip":"番茄炒蛋 > 番茄沙拉——茄紅素是少數加熱後吸收更好的營養素。","warn":"茄紅素是脂溶性的，空腹吃生番茄幾乎吸收不了。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_03', 'phyto', '葉黃素', NULL, '過濾藍光、保護黃斑部、預防老年性黃斑部病變。', '{"name":"葉黃素","emoji":"👁️","alias":"類胡蘿蔔素／眼睛防曬乳","role":"過濾藍光、保護黃斑部、預防老年性黃斑部病變。","dose":"無明確RDA；研究常用約 6–10mg","foods":"菠菜（含量最高）、羽衣甘藍、玉米、蛋黃、枸杞、柳橙","tip":"3C族必備——每天一把菠菜或2顆蛋黃，保護你的黃斑部。","warn":"葉黃素是脂溶性的，配油脂一起吃吸收更好。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_04', 'phyto', '花青素', NULL, '超強抗氧化、保護眼睛微血管、抗發炎、與改善記憶力有關。顏色越深含量越高。', '{"name":"花青素","emoji":"🫐","alias":"多酚類","role":"超強抗氧化、保護眼睛微血管、抗發炎、與改善記憶力有關。顏色越深含量越高。","dose":"無明確RDA","foods":"藍莓、紫葡萄、紫薯、紫高麗菜、桑椹、櫻桃、茄子（皮）","tip":"用眼過度的人——藍莓、桑椹是你的好朋友。冷凍的營養價值不輸新鮮。","warn":"花青素怕高溫，蒸或微波比水煮保留更多。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_05', 'phyto', '兒茶素', NULL, '抗氧化、促進脂肪代謝、口腔保健、抗菌。', '{"name":"兒茶素","emoji":"🍵","alias":"多酚類（綠茶）","role":"抗氧化、促進脂肪代謝、口腔保健、抗菌。","dose":"無明確RDA","foods":"綠茶（最佳來源）、抹茶、白茶、黑巧克力（>70%）","tip":"綠茶用80°C沖泡、泡3分鐘——溫度太高或泡太久會苦且破壞兒茶素。","warn":"空腹喝綠茶可能傷胃；兒茶素會抑制鐵吸收，貧血的人飯後再喝。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_06', 'phyto', '白藜蘆醇', NULL, '抗氧化、保護心血管、抗發炎、與延緩老化研究相關。', '{"name":"白藜蘆醇","emoji":"🍇","alias":"多酚類","role":"抗氧化、保護心血管、抗發炎、與延緩老化研究相關。","dose":"無明確RDA","foods":"紅葡萄皮、花生、藍莓、蔓越莓、紅酒（適量）","tip":"想攝取白藜蘆醇不一定要喝酒——吃紅葡萄（帶皮）、花生也可以。","warn":"紅酒的酒精傷害可能大於白藜蘆醇的好處——不喝酒的人不需要為此開始喝。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_07', 'phyto', '異黃酮', NULL, '類似雌激素的溫和作用、保護骨骼、與改善更年期症狀有關。', '{"name":"異黃酮","emoji":"🫘","alias":"多酚類／植物雌激素","role":"類似雌激素的溫和作用、保護骨骼、與改善更年期症狀有關。","dose":"無明確RDA","foods":"黃豆、豆腐、豆漿、毛豆、味噌、納豆","tip":"更年期女性多吃豆製品有助緩解熱潮紅和骨質流失。","warn":"荷爾蒙相關癌症（如乳癌）患者是否適合大量攝取，務必先諮詢醫師。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_08', 'phyto', '大蒜素', NULL, '抗菌、抗病毒、降血壓、降膽固醇、防血栓。', '{"name":"大蒜素","emoji":"🧄","alias":"有機硫化物","role":"抗菌、抗病毒、降血壓、降膽固醇、防血栓。","dose":"無明確RDA","foods":"大蒜（切碎或壓碎後靜置10分鐘最有效）、洋蔥、韭菜","tip":"大蒜切碎後等10分鐘再煮——酵素需要時間把前驅物轉化為大蒜素。","warn":"空腹生吃大蒜會刺激胃；服用抗凝血藥物者大量食用前宜諮詢。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_09', 'phyto', '蘿蔔硫素', NULL, '啟動人體自身的抗氧化與解毒酵素系統、抗發炎，抗癌研究非常活躍。', '{"name":"蘿蔔硫素","emoji":"🥦","alias":"有機硫化物（十字花科）","role":"啟動人體自身的抗氧化與解毒酵素系統、抗發炎，抗癌研究非常活躍。","dose":"無明確RDA","foods":"青花菜苗（含量最高）、花椰菜、青花菜、高麗菜、白蘿蔔","tip":"切碎後靜置40分鐘讓酵素作用，或搭配一點生的芥末／蘿蔔一起吃，轉化率更高。","warn":"高溫水煮會破壞酵素，快炒、清蒸或涼拌保留最多。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_10', 'phyto', '槲皮素', NULL, '抗過敏、抗發炎、抗氧化、穩定免疫細胞。', '{"name":"槲皮素","emoji":"🧅","alias":"多酚類（類黃酮）","role":"抗過敏、抗發炎、抗氧化、穩定免疫細胞。","dose":"無明確RDA","foods":"洋蔥（紫洋蔥含量最高）、蘋果（帶皮）、莓果、綠茶、花椰菜","tip":"過敏體質的人可以多吃紫洋蔥——天然的抗組織胺，不會嗜睡。","warn":"洋蔥外層含量比內層高，別剝太多層。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_11', 'phyto', '薑黃素', NULL, '強效抗發炎、抗氧化、保護肝臟、與改善關節炎有關。', '{"name":"薑黃素","emoji":"🟡","alias":"多酚類","role":"強效抗發炎、抗氧化、保護肝臟、與改善關節炎有關。","dose":"無明確RDA","foods":"薑黃粉、咖哩、黃芥末","tip":"薑黃素+黑胡椒（胡椒鹼）吸收率大幅提升——吃咖哩記得加黑胡椒與油脂。","warn":"薑黃素單獨吃幾乎不吸收；膽結石、服用抗凝血藥物者大量補充前宜諮詢。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_12', 'phyto', '玉米黃素', NULL, '與葉黃素一起集中在黃斑部中心，過濾藍光、保護視網膜。', '{"name":"玉米黃素","emoji":"🌽","alias":"類胡蘿蔔素（葉黃素的夥伴）","role":"與葉黃素一起集中在黃斑部中心，過濾藍光、保護視網膜。","dose":"無明確RDA","foods":"玉米、蛋黃、枸杞、柳橙、深綠色蔬菜、南瓜","tip":"顧眼睛時玉米黃素常和葉黃素一起補——兩個要搭配。","warn":"脂溶性，配油脂吸收更好。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_13', 'phyto', '蝦紅素', NULL, '抗氧化力極強、保護皮膚、抗發炎、護眼。', '{"name":"蝦紅素","emoji":"🦐","alias":"類胡蘿蔔素（紅色抗氧化）","role":"抗氧化力極強、保護皮膚、抗發炎、護眼。","dose":"無明確RDA","foods":"鮭魚、鮭魚卵、蝦、蟹、紅色藻類","tip":"鮭魚、蝦蟹的紅色就是蝦紅素——來自牠們吃的藻類。","warn":"脂溶性，隨餐吃吸收較好；孕婦補充劑前宜諮詢。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO nutrients (id, category, name, unit, description, data_json) VALUES ('phyto_14', 'phyto', '綠原酸', NULL, '抗氧化，與延緩糖分吸收、調節血糖及血壓的研究有關。', '{"name":"綠原酸","emoji":"☕","alias":"多酚類（咖啡酸家族）","role":"抗氧化，與延緩糖分吸收、調節血糖及血壓的研究有關。","dose":"無明確RDA","foods":"咖啡（主要來源）、蘋果、茄子、地瓜葉、牛蒡","tip":"咖啡的保健成分很多來自綠原酸——但別為此加糖加奶油。","warn":"咖啡因敏感、心悸、失眠者仍要控制咖啡量。"}') ON CONFLICT(id) DO UPDATE SET category=excluded.category, name=excluded.name, unit=excluded.unit, description=excluded.description, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('coworker_dessert', '同事分享甜點', 'social', '{"id":"coworker_dessert","icon":"🍰","title":"同事分享甜點","sys":"social","kw":"甜點 蛋糕 同事 分享 茶水間 點心 請客 拒絕 婉拒 嘴饞 糖 辦公室","driver":"社交促進 × 破戒效應","insight":"這個情境拆開來，是兩股力量在拉扯：一是「社交促進進食」——有人一起吃時，人會不知不覺吃更多；二是「破戒效應（管他的效應）」——一旦覺得破例了，容易乾脆多吃。關鍵不在意志力，而在於吃之前先想好停損點。","ref":{"d":"社交場合會顯著推高攝食量，由 de Castro 等以飲食日誌研究記錄；「破戒／管他的效應」出自 Marlatt 的復發預防模型與 Cochran & Tesser 的 what-the-hell 研究。","s":"de Castro 社會促進進食研究；Marlatt & Gordon 復發預防理論。"},"setup":"週遭的同事人都很好，很喜歡分享東西。今天有人買了一盒甜點放在茶水間，說「大家一起吃」。你正在做飲食控制——到底要不要拿呢？","choices":[{"label":"拿了，開心吃","emoji":"😋","social":"和大家一起吃，氣氛融洽，關係更近。分享美食本來就是同事之間的社交黏著劑。","body":"多了一份熱量。如果今天活動量夠、其他餐有留空間，其實無妨。","mind":"要小心「開始只吃一口，變成吃了好幾口」的『管他的效應』。吃之前先想好吃到哪裡停。"},{"label":"拿一口，其餘分出去","emoji":"🍴","social":"你有參與、有回應大家的好意，關係一樣維繫住，沒有人會覺得你掃興。","body":"嚐到味道、滿足了想吃的心，熱量卻控制住了。這是彈性節制的漂亮示範。","mind":"你證明了「我可以吃、也可以停」，這種掌控感會累積成自信，而不是罪惡感。"},{"label":"拿了，先放著","emoji":"📦","social":"當下有拿、有道謝，社交面過關。同事不會覺得被拒絕。","body":"把決定權延後給未來的自己。但放久了會壞，一直看著不吃也是折磨。","mind":"要誠實面對：放著常常只是拖延決定。給自己一個明確期限——今天下班前決定吃或送人。"},{"label":"婉拒，但用別的方式維繫","emoji":"🙂","social":"偶爾婉拒不會馬上影響關係，但長期都不拿，大家分享時容易尷尬、慢慢疏離。可改天請大家喝飲料補回來。","body":"這一次熱量守住了。前提是你真的不想吃，而不是壓抑想吃的慾望。","mind":"發自內心的不想吃，很好；如果是硬忍，反而可能累積到之後暴食——別把婉拒當成唯一正解。","rec":{"note":"如果剛剛是硬忍下來的——特別留意，別讓壓抑累積成之後的報復性大吃。","link":{"t":"scen","k":"bad_mood","label":"🎭 看看情緒性進食該怎麼辦"}}}],"links":[{"t":"dim","k":"social","label":"🧑‍🤝‍🧑 人際飲食情境"},{"t":"nutri","k":"mineral","label":"⛏️ 礦物質：鉻與血糖穩定"},{"t":"divn","label":"🔮 用飲食占卜看你真正想吃什麼"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('dinner_party', '聚餐應酬', 'social', '{"id":"dinner_party","icon":"🍻","title":"聚餐應酬","sys":"social","kw":"聚餐 應酬 喝酒 勸酒 飯局 宴會 尾牙 慶祝 大餐 敬酒 火鍋 吃到飽","driver":"社交促進 × 酒精去抑制","insight":"這一餐的量，往往不是你決定的，是「人數」和「酒精」決定的：同桌人越多，用餐時間拉長、吃得越多；酒精則會降低自我控制、同時刺激食慾。與其硬忍，不如把環境往好的方向推——先吃菜、放慢、以茶代酒。","ref":{"d":"用餐人數與攝食量的正相關由 de Castro 的社會促進研究記錄；酒精會降低抑制控制並增加短期進食，見酒精與食慾的實驗研究。","s":"de Castro 社會促進進食研究；酒精對食慾與抑制控制的實驗文獻。"},"setup":"下班後的聚餐，滿桌菜色配上一杯杯的酒。氣氛正熱，大家一直勸菜勸酒。你這餐該怎麼過？","choices":[{"label":"放開吃喝，享受當下","emoji":"🥂","social":"完全融入，關係加溫，被當成好相處的人。","body":"高油高鹽加酒精，熱量爆量、隔天容易水腫疲累。","mind":"偶一為之無妨，重點是別讓「難得一次」變成每週好幾次。","rec":{"note":"放開了就放開了，不用有罪惡感——關鍵是隔天用活動量與清淡飲食平衡回來。","link":{"t":"dim","k":"move","label":"🏃 用活動量平衡回來"}}},{"label":"先吃菜再喝、酒少一點","emoji":"🥗","social":"你有喝、有吃、有參與，沒人會覺得你掃興。","body":"先墊胃、放慢喝酒速度，能減少過量與宿醉。","mind":"這是很成熟的折衷——照顧了關係，也照顧了身體。"},{"label":"主動點幾道清爽的菜","emoji":"🍤","social":"幫大家點菜還被感謝，你反而成了餐桌上的貼心角色。","body":"桌上有蔬菜、海鮮這類選擇，整桌人都受惠。","mind":"把環境往好的方向推，比單靠意志力硬忍更省力。"},{"label":"這餐放鬆，隔天調整回來","emoji":"🔄","social":"當下全然投入，關係零損失。","body":"單一餐不會決定體重，隔天多動、清淡就能平衡回來。","mind":"用「一週的視角」而不是「一餐的視角」，才不會因一餐失守就全盤放棄。"}],"links":[{"t":"dim","k":"move","label":"🏃 運動飲食：用活動量平衡"},{"t":"nutri","k":"vitamin","label":"💊 維生素 B 群：代謝與酒精"},{"t":"divn","label":"🔮 飲食占卜"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('family_chopsticks', '家人一直夾菜', 'social', '{"id":"family_chopsticks","icon":"🥢","title":"家人一直夾菜","sys":"social","kw":"家人 長輩 夾菜 團圓 過年 圍爐 媽媽 婆婆 勸食 盛飯 清盤 吃不完 份量","driver":"人情壓力 × 份量錨定","insight":"拆開來看，你的份量其實被兩件事綁架：一是長輩夾菜背後的「愛與人情壓力」，拒絕像是拒絕好意；二是「份量效應」——碗裡越多就吃越多，我們常照盤中量而非飢餓感吃。溫和設界線＋不用清盤，能同時顧到關係與身體。","ref":{"d":"供餐份量越大、實際吃越多（portion size effect）是飲食行為的穩定發現；社會規範與人際壓力也會影響進食量。","s":"份量效應（portion size effect）相關實驗研究；社會規範對進食影響的文獻。"},"setup":"回家吃飯，長輩一口接一口往你碗裡夾菜：「多吃點」「這個對身體好」。碗裡的菜越堆越高，你正在控制份量⋯⋯","choices":[{"label":"收下，謝謝長輩的心意","emoji":"🙏","social":"長輩開心，家庭氣氛溫暖，夾菜是他們表達愛的方式。","body":"份量可能超過需要，尤其飯類澱粉容易過量。","mind":"感受到被愛是好事，但也可以練習溫和地設界線。"},{"label":"收下但不全吃，留在碗裡","emoji":"🍚","social":"接受了心意，長輩不會覺得被拒絕。","body":"吃到適量就停，剩下的不用勉強清盤。","mind":"「不用把碗清空」是很多人要練習的解放——你不欠那碗飯。"},{"label":"溫和說明我在調整，但不掃興","emoji":"💬","social":"誠實但保留餘地，長輩懂了下次就會少夾一點。","body":"份量回到你能掌控的範圍。","mind":"表達需求不等於拒絕愛。清楚而溫柔地說，關係反而更真實。"},{"label":"主動幫忙夾菜給別人","emoji":"🍽️","social":"把焦點轉移，餐桌互動更熱絡，你也不再是被餵食的對象。","body":"自然減少自己被夾的量。","mind":"改變情境的流動，比正面拒絕更不費力。"}],"links":[{"t":"dim","k":"social","label":"🧑‍🤝‍🧑 人際飲食情境"},{"t":"nutri","k":"macro","label":"🍚 三大營養素：澱粉份量"},{"t":"divn","label":"🔮 飲食占卜"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('midnight_gang', '宵夜揪團', 'sleep', '{"id":"midnight_gang","icon":"🌙","title":"宵夜揪團","sys":"sleep","kw":"宵夜 半夜 深夜 鹽酥雞 揪團 睡前 熬夜 嘴饞 FOMO 睡覺 晚上 消夜","driver":"FOMO × 睡眠剝奪","insight":"這裡有兩層：當下想跟，多半是「怕錯過（FOMO）」而不是真餓；而熬夜與睡不夠會讓飢餓素上升、瘦素下降，於是隔天你會更想吃高熱量食物——形成惡性循環。先分清「想參與」還是「想吃」，就贏一半。","ref":{"d":"睡眠剝奪造成 ghrelin 上升、leptin 下降、進而增加食慾與高熱量渴望，由 Spiegel 等實驗與 Taheri 等人群研究確立。","s":"Spiegel et al. 2004；Taheri et al. 2004（睡眠與食慾荷爾蒙）。"},"setup":"晚上11點，群組跳出訊息：「有人要吃宵夜嗎？鹽酥雞喔！」肚子其實不太餓，但好想跟⋯⋯","choices":[{"label":"去，吃想吃的","emoji":"🍗","social":"和朋友一起的深夜時光很珍貴，回憶比熱量重要。","body":"睡前高油高鹽，影響睡眠品質、隔天容易水腫。","mind":"問自己：我是想吃，還是怕錯過（FOMO）？","rec":{"note":"吃了就好好享受——但睡前這一餐最影響睡眠品質，明天記得補一點好眠的營養與作息。","link":{"t":"dim","k":"sleep","label":"😴 看看睡眠與飲食怎麼互相影響"}}},{"label":"去，但只點飲料或小份","emoji":"🥤","social":"人有到、有參與，友情零損失。","body":"睡前負擔小很多，睡眠比較不受影響。","mind":"參與感其實來自「在場」，不一定來自「吃多少」。"},{"label":"去陪聊，不吃","emoji":"💬","social":"陪伴本身就是重點，大家不會在意你有沒有吃。","body":"睡眠與腸胃都守住了。","mind":"你重新定義了「一起」——不是一起吃，是一起在。"},{"label":"婉拒，早點睡","emoji":"😴","social":"偶爾缺席沒關係，長期都不去才要留意疏離。","body":"睡眠是最被低估的健康投資，你選了它。","mind":"睡飽的隔天，你對食物的衝動會明顯下降——這是有生理根據的。"}],"links":[{"t":"dim","k":"sleep","label":"😴 睡眠與飲食"},{"t":"nutri","k":"mineral","label":"⛏️ 礦物質：鎂幫助放鬆入睡"},{"t":"divn","label":"🔮 飲食占卜"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('afternoon_tea', '下午茶手搖', 'eat', '{"id":"afternoon_tea","icon":"🧋","title":"下午茶手搖","sys":"eat","kw":"手搖 飲料 下午茶 珍奶 全糖 含糖 甜 訂飲料 糖分 咖啡 奶茶 珍珠","driver":"習慣迴路 × 血糖起伏","insight":"每天下午的那杯，常常是「線索（同事揪、時間到）→ 行為（訂全糖）→ 獎勵（放鬆一下）」的習慣迴路，未必是身體需要。而全糖一杯的糖常超過一天建議上限，血糖大起大落反而更累。微糖是能長期維持的微調，不是戒斷。","ref":{"d":"習慣由「線索—行為—獎勵」迴路驅動（習慣心理學）；WHO 建議游離糖低於每日總熱量 10%、最好 5% 以下。","s":"習慣心理學（Wood & Neal 等）；WHO 游離糖攝取指引。"},"setup":"下午三點，同事揪團訂手搖飲：「要不要一起？」你的手指停在全糖大杯的按鈕上⋯⋯","choices":[{"label":"全糖大杯，開心","emoji":"🧋","social":"和大家一起訂、一起喝，是辦公室小確幸。","body":"一杯全糖手搖的糖常超過一日建議上限。","mind":"喝之前先想：這杯帶給我的快樂，值得嗎？值得就好好享受。"},{"label":"半糖／微糖中杯","emoji":"🥤","social":"一樣有跟到團，社交零損失。","body":"糖量砍半，負擔小很多，味道其實差不了太多。","mind":"微調而非戒斷，這樣的改變才走得長久。"},{"label":"無糖茶或氣泡水","emoji":"🍵","social":"有訂、有參與，沒人會多說什麼。","body":"幾乎零糖負擔，還能補水。","mind":"你在重新訓練味覺——甜度是可以慢慢往下調的。"},{"label":"這次不喝，改喝水","emoji":"💧","social":"偶爾不跟沒關係，別讓自己顯得格格不入即可。","body":"省下一杯的糖與熱量。","mind":"如果是真的不想喝，很好；如果是硬忍，下次不如選微糖，別壓抑到反彈。"}],"links":[{"t":"dim","k":"eat","label":"🍽️ 吃的飲食型態"},{"t":"nutri","k":"phyto","label":"🌿 植化素：綠原酸、兒茶素"},{"t":"divn","label":"🔮 飲食占卜"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('overtime_hungry', '加班餓到不行', 'stress', '{"id":"overtime_hungry","icon":"🍜","title":"加班餓到不行","sys":"stress","kw":"加班 餓 晚上 外送 泡麵 炸物 累 血糖 忙 深夜 工作 肚子餓","driver":"決策疲勞 × 餓過頭失控","insight":"忙了一整天、又餓又累時，大腦進入省電模式，會自動選最不費力（通常最高油高糖）的選項——這是「決策疲勞」，不是你自制力差。加上餓過頭時血糖偏低，煞車更難踩。先墊一點、事先備好選項，比餓到最後再硬撐有效得多。","ref":{"d":"意志力／決策會因反覆使用而耗損（decision fatigue / ego depletion）；血糖偏低與自我控制下降相關。","s":"Baumeister 等自我耗損研究；血糖與自我控制的相關研究。"},"setup":"晚上九點還在加班，肚子餓得發慌，注意力開始渙散。手機外送 App 就在旁邊⋯⋯","choices":[{"label":"叫炸物／泡麵，快速止餓","emoji":"🍟","social":"（多半是自己一個人）——這是給自己的犒賞。","body":"高油高鈉、血糖大起大落，反而更累。","mind":"餓到失控時最容易亂點。承認累是對的，但食物不是唯一的安慰。","rec":{"note":"泡麵不是不能吃——煮成湯麵、湯少喝或不喝（鈉大多在湯裡），再加一把青菜和一顆蛋，就從「空熱量」變成一餐。下次先在抽屜備點堅果或水果，也能穩住「累到亂點」的衝動。","link":{"t":"nutri","k":"macro","label":"🍚 蛋白質為什麼能穩住血糖與精神"}}},{"label":"叫一份均衡便當","emoji":"🍱","social":"—","body":"有蛋白質、有菜，血糖穩、精神比較能撐。","mind":"照顧自己不等於虧待自己——一份好好的晚餐就是照顧。"},{"label":"先墊點堅果／水果撐著","emoji":"🥜","social":"—","body":"穩住血糖、避免等等回家報復性大吃。","mind":"先止住那股「餓到管他的」的衝動，決定就會清楚很多。"},{"label":"忍到回家再吃","emoji":"🏠","social":"—","body":"回家太晚吃、又太餓，反而容易吃更多。","mind":"硬忍常常不是省，而是延後爆發。餓過頭的忍耐要小心。"}],"links":[{"t":"dim","k":"stress","label":"💢 壓力管理飲食"},{"t":"nutri","k":"macro","label":"🍚 三大營養素：蛋白質穩血糖"},{"t":"divn","label":"🔮 飲食占卜"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('bad_mood', '心情差想吃', 'stress', '{"id":"bad_mood","icon":"😔","title":"心情差想吃","sys":"stress","kw":"心情差 情緒 低落 難過 壓力 想吃 安慰 療癒 憂鬱 煩 不開心 沮喪 情緒性進食","driver":"情緒性進食 × 皮質醇","insight":"這是最需要被溫柔對待的情境。壓力與低落時皮質醇上升，身體會主動渴望高糖高脂的「安慰食物」來快速調節情緒——這是生理反應，不是意志力薄弱。食物能短暫安撫，但填不滿情緒的空。長期解法是找到食物以外的安撫來源，並用自我疼惜取代自責。","ref":{"d":"慢性壓力與皮質醇會增加對高糖高脂「安慰食物」的偏好，由 Dallman、Adam & Epel 等研究提出；自我疼惜可降低失控進食。","s":"Dallman et al.；Adam & Epel 2007（壓力與進食）；Adams & Leary 2007（自我疼惜與飲食）。"},"setup":"今天很不順，情緒低落。你打開冰箱／點開外送，不是因為餓，而是因為「想吃點什麼讓自己好過」⋯⋯","choices":[{"label":"吃，讓自己好過一點","emoji":"🍫","social":"—","body":"食物確實能短暫安撫情緒，這是人類最古老的調節方式之一。","mind":"承認用吃安慰自己，不是軟弱。但要留意：它解決的是情緒，不是問題本身。","rec":{"note":"用吃安撫情緒很正常，別再多加一層罪惡感——但如果這變成常態，值得認識情緒性進食背後的機制。","link":{"t":"dim","k":"stress","label":"💢 認識壓力與情緒性進食"}}},{"label":"吃，但同時做一件照顧自己的事","emoji":"🛁","social":"—","body":"—","mind":"一邊吃、一邊泡澡／聽音樂，讓安慰不只來自食物，情緒的出口就變多了。"},{"label":"先暫停10分鐘，問自己是餓還是情緒","emoji":"⏸️","social":"—","body":"如果不是生理性飢餓，吃了往往填不滿那個空。","mind":"「暫停10分鐘」不是禁止，是給情緒一個被看見的機會。看見了，選擇就多了。"},{"label":"用別的方式安撫（散步／找人聊）","emoji":"🚶","social":"找人說說話，情緒被接住，比一個人悶著吃更有效。","body":"—","mind":"情緒性進食的解藥不是意志力，是找到別的安撫來源。"}],"links":[{"t":"divn","label":"🔮 飲食占卜：看看情緒把你推向什麼食物"},{"t":"dim","k":"stress","label":"💢 壓力管理飲食"},{"t":"nutri","k":"mineral","label":"⛏️ 礦物質：鎂與情緒穩定"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('travel_food', '旅遊美食當前', 'eat', '{"id":"travel_food","icon":"🧳","title":"旅遊美食當前","sys":"eat","kw":"旅遊 出遊 美食 旅行 小吃 假期 放縱 度假 邊走邊吃 名產 大餐 玩","driver":"稀有性心態 × 活動量平衡","insight":"「難得來、只有這裡才吃得到」會放大當下的稀有性，讓人覺得不吃就虧了而過量。但旅遊本身活動量也高，是動態平衡。用「精選幾樣、一天放縱一餐」的節奏，比全都吃或全都忍，都更能享受又回得來。","ref":{"d":"稀有性／機會有限會提高當下的購買與消費衝動（行為經濟學）；體重是能量的長期動態平衡，非單餐決定。","s":"行為經濟學稀有性效應；能量平衡的生理學共識。"},"setup":"難得出遊，滿街都是只有這裡才吃得到的美食。行程滿檔、走了很多路，但也一路都在吃⋯⋯","choices":[{"label":"全都試，旅行就是要吃","emoji":"🍢","social":"和旅伴一起大吃是旅行最棒的回憶之一。","body":"連續幾天熱量爆量，回來可能有感。","mind":"旅行放縱很正常，重點是回到日常後回得來，而不是就此鬆掉。"},{"label":"挑最想吃的幾樣，慢慢品嘗","emoji":"😋","social":"和旅伴分著吃，能試更多樣、又不撐。","body":"聚焦在最值得的，避免每樣都吃到膩、吃到過量。","mind":"「精選」比「全包」更能記住味道，也更享受。"},{"label":"一天放縱一餐，其他正常","emoji":"🍽️","social":"—","body":"給美食留一餐空間，其他餐清爽一點。","mind":"有節奏的放縱，讓你既玩得盡興又不失控。"},{"label":"邊走邊吃，用活動量平衡","emoji":"🚶","social":"—","body":"旅遊本來就走很多路，活動量高，抵掉不少熱量。","mind":"別忘了把「今天走了多少」納入考量——身體是動態平衡的。"}],"links":[{"t":"dim","k":"move","label":"🏃 運動飲食：用活動量平衡"},{"t":"dim","k":"eat","label":"🍽️ 吃的飲食型態"},{"t":"divn","label":"🔮 飲食占卜"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('sofa_after_work', '下班只想癱著', 'move', '{"id":"sofa_after_work","icon":"🛋️","title":"下班只想癱著","sys":"move","kw":"運動 懶 累 下班 沙發 癱 提不起勁 健身 動 拖延 惰性 不想動","driver":"啟動門檻 × 決策疲勞","insight":"「不想動」多半卡在「啟動門檻」，而不是真的沒體力——最難的是從沙發站起來的前三分鐘。把門檻降到最低（先穿上運動鞋、只做10分鐘），行為就容易發生，這是行為激活的核心。真的累就好好休息，但要分清是身體累還是心理惰性。","ref":{"d":"降低行為的啟動成本能提高行動機率（行為激活 behavioral activation）；動機常在行動之後才出現，而非之前。","s":"行為激活的臨床心理學文獻。"},"setup":"下班回到家，全身疲憊只想倒在沙發上。但你今天原本計畫要運動⋯⋯手機和遙控器就在手邊，運動鞋在門口。","choices":[{"label":"直接休息，明天再說","emoji":"😮‍💨","social":"—","body":"身體確實需要休息，但「明天再說」常常會一直延到後天、下週。","mind":"分辨「真的累」和「心理惰性」——前者該休息，後者往往動起來就好了。"},{"label":"只做10分鐘，做完再決定","emoji":"⏱️","social":"—","body":"10分鐘門檻很低，身體熱起來後常會想多做一點。","mind":"降低啟動門檻是對抗惰性最有效的方法——先穿上運動鞋，你就贏一半了。"},{"label":"換成輕鬆的散步或伸展","emoji":"🚶","social":"—","body":"低強度活動一樣促進循環、幫助放鬆，比完全不動好太多。","mind":"運動不是全有全無——累的時候「少做一點」遠勝於「整個放棄」。"},{"label":"今天真的太累，好好睡","emoji":"😴","social":"—","body":"睡眠不足時硬練，反而增加受傷與過度訓練的風險。","mind":"休息也是訓練的一部分。誠實的休息，不是藉口。","rec":{"note":"如果是真的累就好好睡——但如果每天都「太累」，也許問題出在睡眠品質，值得看看。","link":{"t":"dim","k":"sleep","label":"😴 看看睡眠與飲食"}}}],"links":[{"t":"dim","k":"move","label":"🏃 運動與飲食"},{"t":"dim","k":"sleep","label":"😴 睡眠"},{"t":"divn","label":"🔮 飲食占卜"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('reward_after_workout', '運動完想犒賞', 'move', '{"id":"reward_after_workout","icon":"🏆","title":"運動完想犒賞","sys":"move","kw":"運動 犒賞 獎勵 練完 健身後 大吃 消耗 熱量 補償 珍奶 蛋白質 增肌","driver":"道德許可 × 補償心理","insight":"「我運動了，所以可以吃」是「道德許可效應」——做了一件好事後，會覺得有資格放縱，結果補回來的熱量常超過剛剛消耗的。把運動和吃分開看：運動後補蛋白＋碳水是幫肌肉修復的「投資」，不是犒賞，這樣努力才不會被吃回去。","ref":{"d":"先前的好行為會讓人合理化之後的放縱（moral licensing）；運動後補充蛋白質與碳水有助肌肉修復與肝醣回補。","s":"moral licensing 研究（如 Monin & Miller）；運動營養（ISSN）立場聲明。"},"setup":"剛結束一場累人的運動，滿身大汗、超有成就感。腦中冒出一個念頭：「我今天運動這麼多，吃點好料犒賞自己應該可以吧？」","choices":[{"label":"大吃一頓犒賞自己","emoji":"🍔","social":"和運動夥伴一起吃很開心。","body":"一份炸物＋手搖的熱量，常常遠超過剛剛運動消耗的。","mind":"「運動了所以可以亂吃」是最常見的補償心理——很容易把辛苦練的成果吃回去。"},{"label":"補一份優質蛋白＋碳水","emoji":"🍳","social":"—","body":"運動後補蛋白質與碳水，正是肌肉修復與肝醣回補的黃金時機。","mind":"這不是犒賞、是投資——你在讓剛剛的努力真正發揮效果。","rec":{"note":"運動後大約30分鐘～2小時內補蛋白＋碳水最有效，這是幫肌肉長回來的關鍵。","link":{"t":"nutri","k":"amino","label":"🧬 白胺酸與肌肉合成"}}},{"label":"正常吃一餐，不特別加碼","emoji":"🍱","social":"—","body":"依平常份量吃就好，不需要因為運動而額外加量。","mind":"把運動和吃分開看——運動是為了健康，不是為了換取吃的額度。"},{"label":"用非食物的方式犒賞","emoji":"🛁","social":"—","body":"泡個熱水澡、好好休息，疲勞一樣被照顧到。","mind":"犒賞不一定要用吃——找到別的獎勵，才不會讓努力和暴食綁在一起。"}],"links":[{"t":"dim","k":"move","label":"🏃 運動與飲食"},{"t":"nutri","k":"amino","label":"🧬 胺基酸"},{"t":"nutri","k":"macro","label":"🍚 三大營養素"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('phone_before_bed', '睡前滑手機停不下來', 'sleep', '{"id":"phone_before_bed","icon":"📱","title":"睡前滑手機停不下來","sys":"sleep","kw":"睡前 手機 滑 熬夜 追劇 藍光 失眠 賴床 停不下來 影片 報復性熬夜 晚睡","driver":"藍光 × 即時獎勵迴圈","insight":"拆開來有三件事：睡前藍光抑制褪黑激素，讓你越滑越清醒；每支短影音都是「即時獎勵」，形成「再看一個」的無限迴圈；而報復性熬夜常源於白天缺乏屬於自己的時間。對抗它靠的是事先設好的停止點，不是當下的意志力。","ref":{"d":"夜間藍光會抑制褪黑激素分泌、延後入睡；睡前使用螢幕與入睡困難相關（睡眠醫學研究）。","s":"光照與褪黑激素分泌的睡眠研究。"},"setup":"已經躺在床上了，時間也不早了。手指卻還在螢幕上滑——一支影片接著一支，「再看一個就睡」重複了好幾次⋯⋯","choices":[{"label":"再看一下，反正睡不著","emoji":"📲","social":"—","body":"藍光抑制褪黑激素分泌，越滑越睡不著，形成惡性循環。","mind":"是「睡不著才滑」，還是「滑了才睡不著」？常常是後者。"},{"label":"設一個明確的停止點","emoji":"⏰","social":"—","body":"給自己「到某個時間就放下」的界線，讓大腦知道要準備休息了。","mind":"對抗「再一個就好」的無限循環，靠的是事先設定的規則，不是當下的意志力。"},{"label":"放下手機，做點助眠的事","emoji":"🌙","social":"—","body":"調暗燈光、深呼吸或伸展，幫助身體切換到睡眠模式。","mind":"睡前儀式能讓大腦形成條件反射——做久了，一做就想睡。","rec":{"note":"睡不好也會影響隔天的食慾與情緒——睡眠是五大系統裡最被低估的一環。","link":{"t":"dim","k":"sleep","label":"😴 睡眠與飲食"}}},{"label":"承認是報復性熬夜，想想為什麼","emoji":"💭","social":"—","body":"熬夜滑手機常是白天太忙、想抓回一點「自己的時間」。","mind":"看見背後的需求（想要屬於自己的時間），才能真正解決，而不是責怪自己。"}],"links":[{"t":"dim","k":"sleep","label":"😴 睡眠與飲食"},{"t":"nutri","k":"amino","label":"🧬 色胺酸助眠"},{"t":"nutri","k":"mineral","label":"⛏️ 鎂幫助放鬆"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('work_pressure', '壓力大到想擺爛', 'stress', '{"id":"work_pressure","icon":"🌋","title":"壓力大到想擺爛","sys":"stress","kw":"壓力 擺爛 崩潰 焦慮 工作 忙 喘不過氣 想放棄 逃避 累 撐不住 情緒","driver":"壓力逃避 × 全有全無思維","insight":"高壓時大腦會放大所有任務、觸發「逃避（擺爛）」反應，並落入「反正做不完，乾脆全部放棄」的全有全無思維。破解點是把任務拆到最小、先完成一件——完成的成就感會釋放多巴胺，打破僵局。暫停、拆小、求助，都是降皮質醇、拿回掌控的有效方式。","ref":{"d":"壓力會促發逃避行為；把目標拆小、獲得小的達成感有助啟動行動（目標拆解與行為激活）。","s":"壓力生理學；目標拆解與行為激活的心理學文獻。"},"setup":"事情多到快喘不過氣，截止日一個接一個。你感覺自己快撐不住，一股「乾脆全部擺爛」的衝動湧上來⋯⋯","choices":[{"label":"擺爛，什麼都不管了","emoji":"🫠","social":"—","body":"長期高壓確實需要釋放，但完全放棄常換來更大的焦慮反彈。","mind":"「擺爛」有時是身體在求救——它在說：我需要休息，不是我沒用。"},{"label":"先處理最小的一件事","emoji":"✅","social":"—","body":"完成一件小事會釋放多巴胺，打破「什麼都做不動」的僵局。","mind":"壓力大時大腦會放大所有任務——把它拆到最小，行動就變得可能。"},{"label":"暫停10分鐘，深呼吸／走一走","emoji":"🌬️","social":"—","body":"短暫抽離能降低皮質醇，讓思緒重新清晰。","mind":"暫停不是浪費時間，是幫大腦重開機——回來後效率反而更高。","rec":{"note":"壓力大時特別容易情緒性進食——先照顧情緒，再面對食物。","link":{"t":"scen","k":"bad_mood","label":"🎭 心情差想吃該怎麼辦"}}},{"label":"找人說出來，不自己扛","emoji":"🫂","social":"把壓力說出口，光是被理解就能減輕一半。","body":"—","mind":"求助不是軟弱——願意說出來，是照顧自己的能力。"}],"links":[{"t":"scen","k":"bad_mood","label":"🎭 心情差想吃"},{"t":"dim","k":"stress","label":"💢 壓力管理"},{"t":"nutri","k":"mineral","label":"⛏️ 鎂與情緒穩定"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('forced_drink', '飯局被勸酒', 'social', '{"id":"forced_drink","icon":"🍺","title":"飯局被勸酒","sys":"social","kw":"勸酒 敬酒 喝酒 應酬 乾杯 酒 拒絕 拚酒 主管 飯局 面子 以茶代酒","driver":"從眾壓力 × 面子文化","insight":"「不喝就是不給面子」是社會從眾與面子文化的雙重壓力，讓人明明不想喝卻難拒絕。但要記得：酒精過量的代價由你的身體承擔，不是敬酒的人。事先準備好一句禮貌而明確的界線（以茶代酒、開車、身體因素），就能同時顧到關係與健康。","ref":{"d":"個體會因群體壓力而順從，即使違背自身判斷（Asch 從眾實驗）；過量飲酒對肝臟與健康有明確風險。","s":"社會心理學從眾研究（Asch）；WHO 酒精與健康資料。"},"setup":"飯局上氣氛正熱，有人舉杯走過來：「來啦，這杯一定要乾！不喝就是不給面子。」你其實不太想喝⋯⋯","choices":[{"label":"乾了，不想掃大家的興","emoji":"🥃","social":"當下氣氛維繫住，但一杯接一杯很難停。","body":"酒精傷肝、增加熱量、隔天宿醉，過量風險高。","mind":"「不給面子」是一種社交壓力——但你的身體不該為別人的期待買單。"},{"label":"以茶／飲料代酒敬回去","emoji":"🍵","social":"用行動回應敬意，多數場合都能接受，還顯得體。","body":"避開酒精負擔，也不失禮。","mind":"「我心領了，以茶代酒」——設界線也可以很有禮貌。"},{"label":"抿一口意思到，就放下","emoji":"🍷","social":"有回應、有參與，面子顧到了。","body":"象徵性喝一點，控制總量。","mind":"你可以參與儀式，而不必全盤照單全收。"},{"label":"直接說今天不喝（開車／身體因素）","emoji":"🚗","social":"用明確理由婉拒，多數人都會尊重，也不好強迫。","body":"完全避開酒精。","mind":"「我今天不喝」是完整的句子，不需要過度解釋或道歉。"}],"links":[{"t":"dim","k":"social","label":"🧑‍🤝‍🧑 人際飲食"},{"t":"scen","k":"dinner_party","label":"🎭 聚餐應酬"},{"t":"nutri","k":"vitamin","label":"💊 B群與酒精代謝"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
INSERT INTO scenarios (id, title, category, data_json) VALUES ('diet_teased', '被關心身材', 'social', '{"id":"diet_teased","icon":"💬","title":"被關心身材","sys":"social","kw":"身材 減肥 被虧 評論 身體 比較 外貌 胖 瘦 關心 壓力 焦慮 自尊","driver":"身材污名 × 羞愧循環","insight":"被評論身材會帶來羞愧，而研究發現：羞愧與體重污名不但無助於改變，反而更容易觸發情緒性進食與放棄。把主導權拿回來、溫和設界線，並用「自我疼惜」取代自責，才能跳出「被評論→難過→大吃→更自責」的惡性循環。你的身體不是公共評論區。","ref":{"d":"體重污名與羞愧和更多失控進食、心理壓力相關；自我疼惜則與較穩定的飲食調節相關。","s":"體重污名（weight stigma）與進食研究；Adams & Leary 2007（自我疼惜與飲食）。"},"setup":"聚會上有人「關心」地說：「你最近好像有變胖喔？」「還在減肥啊，有效嗎？」你心裡一沉，不知道怎麼回⋯⋯","choices":[{"label":"當場尷尬，回家更想吃","emoji":"😞","social":"—","body":"被評論身材的壓力，常轉化成情緒性進食。","mind":"別人隨口一句話，不該定義你的價值——你的身體不是公共評論區。"},{"label":"幽默帶過，不往心裡去","emoji":"😎","social":"輕鬆化解，也讓對方知道這話題到此為止。","body":"—","mind":"把主導權拿回來——你決定哪些話值得放在心上。"},{"label":"溫和設界線：不想聊身材","emoji":"🙅","social":"明確表達，多數人會識相地換話題。","body":"—","mind":"「我們聊點別的吧」是健康的界線——保護自己不是沒禮貌。"},{"label":"提醒自己：健康是為自己，不是為別人的眼光","emoji":"💪","social":"—","body":"—","mind":"當動機來自「照顧自己」而非「別人怎麼看」，才走得長久、也更快樂。","rec":{"note":"如果被評論後很想大吃——那是情緒性進食，值得溫柔地接住自己。","link":{"t":"scen","k":"bad_mood","label":"🎭 心情差想吃"}}}],"links":[{"t":"scen","k":"bad_mood","label":"🎭 心情差想吃"},{"t":"dim","k":"stress","label":"💢 壓力管理"},{"t":"dim","k":"social","label":"🧑‍🤝‍🧑 人際"}]}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, category=excluded.category, data_json=excluded.data_json;
